From 04a139b150280f5d677e4d05aad4052d08e3d95c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:43:32 +0100
Subject: [PATCH] folder: offer "Open Folder With" for folders on the desktop

Desktop items use desktop:/ URLs, and KFileItemActions skips the Open
With actions for folders that aren't local, so desktop folders had no
"Open Folder With" entry. Hand it the items' local URLs instead.

BUG: 451214
---
 containments/desktop/plugins/folder/foldermodel.cpp | 10 +++++++++-
 1 file changed, 9 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..feecc2437d 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -2076,7 +2076,15 @@ void FolderModel::openContextMenu(QQuickItem *visualParent, Qt::KeyboardModifier
         // Start adding the actions:
         // "Open" and "Open with" actions
         if (!isTrash && !isTrashLink) {
-            m_fileItemActions->setItemListProperties(itemProperties);
+            // Use local URLs where possible (e.g. for desktop:/), as KFileItemActions
+            // doesn't offer "Open Folder With" for non-local folders
+            KFileItemList localItems;
+            localItems.reserve(items.count());
+            for (KFileItem item : std::as_const(items)) {
+                item.setUrl(item.mostLocalUrl());
+                localItems.append(item);
+            }
+            m_fileItemActions->setItemListProperties(KFileItemListProperties(localItems));
             m_fileItemActions->insertOpenWithActionsTo(nullptr, menu, QStringList());
         }

